def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 18.0 if hp > 3 else 45.0))

    prev_bids = []
    strong_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) > 0 and opp.get('hp', 0) > 0:
                strong_bids.append(float(bid))

    top_prev = max(prev_bids) if prev_bids else 0.0
    top_strong = max(strong_bids) if strong_bids else top_prev
    second_strong = 0.0
    if len(strong_bids) >= 2:
        second_strong = sorted(strong_bids)[-2]
    elif len(prev_bids) >= 2:
        second_strong = sorted(prev_bids)[-2]

    units = supply / WATER_REQ
    tight = units < 2.0
    comfortable = units >= 2.0

    emergency = hp <= 2 or no_water >= 2
    pressured = hp <= 4 or no_water >= 1

    if emergency:
        bid = max(92.0, top_strong + 2.0, second_strong + 4.0)
    elif tight:
        bid = max(78.0, second_strong + 2.0)
    elif comfortable and hp >= 5 and no_water == 0:
        bid = 24.0
        if top_prev < 40:
            bid = 18.0
    else:
        bid = max(38.0, min(88.0, second_strong + 1.5))
        if pressured:
            bid = max(bid, 62.0)

    if budget < bid:
        if emergency:
            return float(budget)
        bid = max(0.0, min(budget, budget * 0.85))

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    base_bid = DAILY_SALARY * 0.55

    # If supply is low relative to players, increase base bid
    if current_supply < WATER_REQ * (num_alive_opponents + 1): 
        base_bid = DAILY_SALARY * 0.65
    if current_supply < WATER_REQ * 2: 
        base_bid = DAILY_SALARY * 0.75

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    bid = base_bid
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.85: 
            if my_current_hp > 3: 
                bid = max(base_bid, highest_prev_bid * 0.98)
            else: 
                bid = max(base_bid, highest_prev_bid + 5)
                bid = max(bid, DAILY_SALARY * 0.95)
        elif highest_prev_bid >= DAILY_SALARY * 0.5: 
            bid = max(base_bid, highest_prev_bid + 2)
        else: 
            bid = max(base_bid, highest_prev_bid * 1.1)

    if my_current_hp <= 2: 
        bid = max(bid, DAILY_SALARY * 0.99)
    elif my_current_hp <= 4 and my_status['no_water_days'] > 0: 
        bid = max(bid, DAILY_SALARY * 0.90)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2: 
        if my_current_hp <= 3: 
            bid = max(bid, DAILY_SALARY * 0.99)
        elif my_current_hp >= 8 and my_current_budget > DAILY_SALARY * 2: 
            bid = min(bid, DAILY_SALARY * 0.7)
            bid = max(bid, DAILY_SALARY * 0.4)

    final_bid = min(my_current_budget, bid)
    final_bid = max(1.0, final_bid)

    return float(final_bid)

